@extends('layouts.admin') @section('title',$supplier->exists?'Edit Supplier':'Add Supplier') @section('page-title','Supplier editor') @section('content')<div class="ad-page-head"><div><a class="ad-back" href="{{ route('admin.suppliers.index') }}">← Suppliers</a><h2>{{ $supplier->exists?'Edit '.$supplier->name:'Create supplier' }}</h2></div></div><form class="card p-4" method="POST" action="{{ $supplier->exists?route('admin.suppliers.update',$supplier):route('admin.suppliers.store') }}">@csrf @if($supplier->exists)@method('PUT')@endif<div class="row g-3">@foreach(['name'=>'Supplier name','contact_name'=>'Contact person','email'=>'Email','phone'=>'Phone','website'=>'Website','city'=>'City','country'=>'Country','tax_id'=>'Tax ID'] as $n=>$l)<div class="col-md-6"><label class="form-label">{{ $l }}</label><input class="form-control" name="{{ $n }}" value="{{ old($n,$supplier->$n) }}" {{ $n==='name'?'required':'' }}></div>@endforeach<div class="col-md-6"><label class="form-label">Lead time (days)</label><input type="number" min="0" class="form-control" name="lead_time_days" value="{{ old('lead_time_days',$supplier->lead_time_days??0) }}"></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" @selected($supplier->status!=='inactive')>Active</option><option value="inactive" @selected($supplier->status==='inactive')>Inactive</option></select></div><div class="col-12"><label class="form-label">Address</label><textarea class="form-control" name="address">{{ old('address',$supplier->address) }}</textarea></div><div class="col-12"><label class="form-label">Products supplied</label><div class="ad-check-grid">@php($selected=old('products',$supplier->exists?$supplier->products()->pluck('products.id')->all():[])) @foreach($products as $p)<label class="ad-check"><input type="checkbox" name="products[]" value="{{ $p->id }}" @checked(in_array($p->id,$selected))><span><strong>{{ $p->name }}</strong><small>{{ $p->sku }}</small></span></label>@endforeach</div></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes" rows="4">{{ old('notes',$supplier->notes) }}</textarea></div></div><button class="btn btn-primary mt-4">Save supplier</button></form>@endsection